# generated by scripts/hwdb_gen.py from the hwdb TOML files, do not edit (source: scripts/ghidra/hwdb_export.py)
# @category hwdb
# Ghidra script (PyGhidra / Jython-safe syntax): write function names, comments and addresses of the
# current program into hwdb/fw/<binary>.toml. Hand fields (role, regs, src, conf) of known functions are kept.
# Args: [binary-name] [repo-root]. Default binary = lowercase program name without extension; root = $US48_REPO or cwd.
# The .toml must stay in the restricted subset: flat tables, one-line scalars, one-line string arrays.
import os
import re
import time


def parse_min(text):
    """Restricted TOML -> (header_comments, doc). doc: {path_tuple: dict}; [[x]] tables -> {path_tuple: [dict,..]}."""
    head, doc, cur, started = [], {}, None, False
    for line in text.splitlines():
        s = line.strip()
        if not started and (s.startswith("#") or not s):
            head.append(line)
            continue
        if not s or s.startswith("#"):
            continue
        started = True
        m = re.match(r"^\[\[([^\]]+)\]\]$", s)
        if m:
            path = tuple(m.group(1).split("."))
            cur = {}
            doc.setdefault(path, []).append(cur)
            continue
        m = re.match(r"^\[([^\]]+)\]$", s)
        if m:
            path = tuple(m.group(1).split("."))
            cur = doc.setdefault(path, {})
            continue
        k, _, v = s.partition("=")
        cur[k.strip()] = _val(v.strip())
    while head and not head[-1].strip():
        head.pop()
    return head, doc


def _val(v):
    if v.startswith('"'):
        return v[1:-1].replace("\\\"", '"').replace("\\\\", "\\")
    if v.startswith("["):
        return [_val(x.strip()) for x in re.findall(r'"(?:[^"\\]|\\.)*"|[^,\s\[\]]+', v)]
    if v in ("true", "false"):
        return v == "true"
    return int(v, 0)


def _fmt(k, v):
    if isinstance(v, bool):
        return "%s = %s" % (k, "true" if v else "false")
    if isinstance(v, int):
        return "%s = 0x%08x" % (k, v) if k in ("addr", "base") else "%s = %d" % (k, v)
    if isinstance(v, list):
        return "%s = [%s]" % (k, ", ".join(_q(x) if not isinstance(x, int) else str(x) for x in v))
    return "%s = %s" % (k, _q(v))


def _q(s):
    return '"%s"' % s.replace("\\", "\\\\").replace('"', "'")


FUNC_ORDER = ("name", "addr", "size", "role", "regs", "src", "conf")


def merge(doc, binary, prog, funcs, comments, today):
    """funcs: [(name, addr, size, comment)]; comments: [(addr, kind, text)]. Updates doc in place."""
    bpath = ("binary", binary)
    doc.setdefault(bpath, {"desc": prog, "base": 0, "arch": ""})
    old = {}
    for path, t in list(doc.items()):
        if len(path) == 4 and path[:2] == bpath and path[2] == "func":
            old[t["addr"]] = (path, t)
    for name, addr, size, cmt in funcs:
        if addr in old:
            path, t = old.pop(addr)
            del doc[path]
        else:
            t = {"src": "ghidra %s %s" % (prog, today), "conf": "I"}
        t["name"], t["addr"] = name, addr
        if size:
            t["size"] = size
        if cmt:
            t["role"] = cmt
        doc[bpath + ("func", re.sub(r"\W", "_", name))] = t
    for path, t in old.values():
        doc[path] = t  # not in Ghidra (or default-named elsewhere): keep the hand entry
    doc[bpath + ("comment",)] = [{"addr": a, "kind": k, "text": x, "src": "ghidra %s %s" % (prog, today), "conf": "I"}
                                 for a, k, x in sorted(comments)]
    return doc


def render(head, doc, binary):
    out = list(head) + ([""] if head else [])
    bpath = ("binary", binary)
    out.append("[binary.%s]" % binary)
    for k, v in doc[bpath].items():
        out.append(_fmt(k, v))
    out.append("")
    fk = sorted((p for p in doc if len(p) == 4 and p[:2] == bpath and p[2] == "func"), key=lambda p: doc[p]["addr"])
    for p in fk:
        out.append("[%s]" % ".".join(p))
        t = doc[p]
        for k in FUNC_ORDER:
            if k in t:
                out.append(_fmt(k, t[k]))
        for k in t:
            if k not in FUNC_ORDER:
                out.append(_fmt(k, t[k]))
        out.append("")
    for c in doc.get(bpath + ("comment",), []):
        out.append("[[binary.%s.comment]]" % binary)
        for k, v in c.items():
            out.append(_fmt(k, v))
        out.append("")
    return "\n".join(out)


def ghidra_main():
    from ghidra.program.model.listing import CodeUnit  # noqa: F401 (only inside Ghidra)
    prog = currentProgram.getName()  # noqa: F821
    args = list(getScriptArgs())  # noqa: F821
    binary = args[0] if args else re.sub(r"\W", "_", os.path.splitext(prog)[0].lower())
    root = args[1] if len(args) > 1 else os.environ.get("US48_REPO", os.getcwd())
    path = os.path.join(root, "hwdb", "fw", binary + ".toml")
    funcs = []
    for f in currentProgram.getFunctionManager().getFunctions(True):  # noqa: F821
        n = f.getName()
        if re.match(r"^(FUN|thunk_FUN)_[0-9a-fA-F]+$", n):
            continue
        funcs.append((n, f.getEntryPoint().getOffset(), int(f.getBody().getNumAddresses()), f.getComment() or ""))
    comments = []
    listing = currentProgram.getListing()  # noqa: F821
    for kind, cu_kind in (("eol", CodeUnit.EOL_COMMENT), ("pre", CodeUnit.PRE_COMMENT)):
        it = listing.getCommentAddressIterator(cu_kind, currentProgram.getMemory(), True)  # noqa: F821
        for a in it:
            comments.append((a.getOffset(), kind, listing.getComment(cu_kind, a).replace("\n", " ")))
    text = open(path).read() if os.path.exists(path) else ""
    head, doc = parse_min(text)
    if not head:
        head = ["# %s functions exported from Ghidra program %s (hand fields kept)." % (binary, prog)]
    merge(doc, binary, prog, funcs, comments, time.strftime("%Y-%m-%d"))
    with open(path, "w") as fh:
        fh.write(render(head, doc, binary) + "\n")
    print("hwdb_export: %d functions, %d comments -> %s" % (len(funcs), len(comments), path))


try:
    currentProgram  # noqa: F821
except NameError:
    pass
else:
    ghidra_main()
